html:
{% set company_logo = frappe.db.get_value("Company", doc.company, "company_logos") %}
{% set company_phone = frappe.db.get_value("Company", doc.company, "phone_no") %}
{% set company_email = frappe.db.get_value("Company", doc.company, "email") %}
{% set company_website = frappe.db.get_value("Company", doc.company, "website") %}
{% set quotations = doc.items | selectattr("prevdoc_docname") | map(attribute="prevdoc_docname") | unique | list %}
{% set sales_person_name = "" %}
{% if doc.sales_team and doc.sales_team[0].sales_person %}
	{% set sales_person_name = frappe.db.get_value("Sales Person", doc.sales_team[0].sales_person, "sales_person_name") or doc.sales_team[0].sales_person %}
{% endif %}
{% set bank_accounts = frappe.get_all("Bank Account", filters={"company": doc.company, "is_company_account": 1}, fields=["account_name", "bank", "iban", "bank_account_no"], order_by="is_default desc", limit_page_length=1) %}
{% set bank_account = bank_accounts[0] if bank_accounts else none %}
{% set bank_name = frappe.db.get_value("Bank", bank_account.bank, "bank_name") if bank_account and bank_account.bank else "" %}
{% set bank_swift = frappe.db.get_value("Bank", bank_account.bank, "swift_number") if bank_account and bank_account.bank else "" %}
{% set ns = namespace(item_discount_total=0) %}
{% for item in doc.items %}
	{% set ns.item_discount_total = ns.item_discount_total + (frappe.utils.flt(item.qty) * frappe.utils.flt(item.discount_amount)) %}
{% endfor %}
<div class="ls-order">
	<style>
		.ls-order {
			font-family: Arial, Helvetica, sans-serif;
			font-size: 11px;
			color: #1a1a1a;
		}
		.ls-order table {
			border-collapse: collapse;
			width: 100%;
		}
		.ls-order .header-table td {
			vertical-align: top;
			padding: 0;
		}
		.ls-order .logo-cell {
			width: 80px;
			padding-right: 12px;
		}
		.ls-order .logo-cell img {
			max-width: 80px;
			max-height: 80px;
		}
		.ls-order .company-name {
			font-size: 16px;
			font-weight: bold;
			margin: 2px 0 6px;
		}
		.ls-order .company-details div {
			line-height: 1.5;
			color: #333;
		}
		.ls-order .order-title-cell {
			text-align: right;
			width: 45%;
		}
		.ls-order .order-title {
			font-size: 26px;
			font-weight: bold;
			letter-spacing: 1px;
			margin-bottom: 10px;
		}
		.ls-order .order-meta {
			width: 100%;
		}
		.ls-order .order-meta td {
			padding: 1px 0;
			white-space: nowrap;
		}
		.ls-order .order-meta .im-label {
			text-align: right;
			text-transform: uppercase;
			font-size: 9px;
			color: #555;
			padding-right: 10px;
			font-weight: bold;
		}
		.ls-order .order-meta .im-value {
			text-align: right;
			font-weight: bold;
		}
		.ls-order hr.rule {
			border: none;
			border-top: 2px solid #000;
			margin: 12px 0;
		}
		.ls-order .section-label {
			text-transform: uppercase;
			font-size: 9px;
			font-weight: bold;
			color: #555;
			letter-spacing: 0.5px;
		}
		.ls-order .customer-table td {
			padding: 2px 10px 2px 0;
			vertical-align: top;
		}
		.ls-order .customer-table .field-label {
			width: 95px;
			font-weight: bold;
		}
		.ls-order .items-table {
			margin-top: 16px;
			border: 1px solid #000;
		}
		.ls-order .items-table th,
		.ls-order .items-table td {
			border: 1px solid #000;
			padding: 5px 6px;
			font-size: 10.5px;
			word-wrap: break-word;
		}
		.ls-order .items-table th {
			text-transform: uppercase;
			font-size: 9.5px;
			background: #f2f2f2;
			text-align: left;
		}
		.ls-order .items-table .item-desc {
			font-size: 9.5px;
			color: #555;
			margin-top: 2px;
		}
		.ls-order .items-table .item-desc p {
			margin: 0;
		}
		.ls-order .items-table .num {
			text-align: right;
		}
		.ls-order .items-table .center {
			text-align: center;
		}
		.ls-order .items-table tfoot td {
			font-weight: bold;
			border-top: 2px solid #000;
		}
		.ls-order .totals-table {
			width: 260px;
			float: right;
		}
		.ls-order .totals-table td {
			padding: 3px 0;
		}
		.ls-order .totals-table .t-value {
			text-align: right;
		}
		.ls-order .totals-table .grand td {
			border-top: 2px solid #000;
			font-weight: bold;
			font-size: 13px;
			padding-top: 6px;
		}
		.ls-order .words-bank {
			width: 55%;
			float: left;
		}
		.ls-order .words-box {
			margin-bottom: 12px;
		}
		.ls-order .bank-table td {
			padding: 1px 8px 1px 0;
		}
		.ls-order .bank-table .b-label {
			width: 90px;
			color: #333;
		}
		.ls-order .clearfix::after {
			content: "";
			display: table;
			clear: both;
		}
		.ls-order .terms {
			margin-top: 16px;
			clear: both;
		}
		.ls-order .terms ol {
			margin: 4px 0 0 16px;
			padding: 0;
		}
		.ls-order .signature {
			margin-top: 70px;
		}
		.ls-order .signature .line {
			border-top: 1px solid #000;
			width: 280px;
			padding-top: 4px;
			font-size: 9.5px;
			color: #555;
		}
		.ls-order .print-footer {
			display: flex;
			justify-content: space-between;
			font-size: 9px;
			color: #555;
		}
	</style>

	<table class="header-table">
		<tr>
			{% if company_logo %}
			<td class="logo-cell">
				<img src="{{ frappe.utils.get_url(company_logo) }}" alt="{{ doc.company }}" />
			</td>
			{% endif %}
			<td>
				<div class="company-name">{{ doc.company }}</div>
				<div class="company-details">
					{% if doc.company_address_display %}{{ doc.company_address_display }}{% endif %}
					{% if company_phone %}<div>Tel {{ company_phone }}{% if company_email %} &middot; {{ company_email }}{% endif %}</div>{% endif %}
					{% if company_website %}<div>{{ company_website }}</div>{% endif %}
				</div>
			</td>
			<td class="order-title-cell">
				<div class="order-title">{{ _("SALES ORDER") }}</div>
				<table class="order-meta">
					<tr>
						<td class="im-label">{{ _("Order No.") }}</td>
						<td class="im-value">{{ doc.name }}</td>
					</tr>
					<tr>
						<td class="im-label">{{ _("Order Date") }}</td>
						<td class="im-value">{{ frappe.utils.format_date(doc.transaction_date) }}</td>
					</tr>
					{% if doc.delivery_date %}
					<tr>
						<td class="im-label">{{ _("Delivery Date") }}</td>
						<td class="im-value">{{ frappe.utils.format_date(doc.delivery_date) }}</td>
					</tr>
					{% endif %}
					{% if quotations %}
					<tr>
						<td class="im-label">{{ _("Quotation") }}</td>
						<td class="im-value">{{ quotations | join(", ") }}</td>
					</tr>
					{% endif %}
				</table>
			</td>
		</tr>
	</table>

	<hr class="rule" />

	<table class="customer-table">
		<tr>
			<td class="field-label">{{ _("Customer Name") }}</td>
			<td style="width: 35%">{{ doc.customer_name }}</td>
			<td class="field-label">{{ _("Phone") }}</td>
			<td>{{ doc.contact_mobile or "" }}</td>
		</tr>
		<tr>
			<td class="field-label">{{ _("Customer ID") }}</td>
			<td>{{ doc.customer }}</td>
			<td class="field-label">{{ _("Email") }}</td>
			<td>{{ doc.contact_email or "" }}</td>
		</tr>
		<tr>
			<td class="field-label" style="vertical-align: top">{{ _("Address") }}</td>
			<td style="vertical-align: top">{{ doc.address_display or "" }}</td>
			<td class="field-label">{{ _("Sales Person") }}</td>
			<td>{{ sales_person_name }}</td>
		</tr>
	</table>

	<table class="items-table">
		<thead>
			<tr>
				<th class="center" style="width: 5%">{{ _("Sl. No.") }}</th>
				<th style="width: 12%">{{ _("Item Code") }}</th>
				<th style="width: 27%">{{ _("Item Name") }}</th>
				<th class="center" style="width: 7%">{{ _("Qty") }}</th>
				<th class="center" style="width: 7%">{{ _("UOM") }}</th>
				<th class="num" style="width: 14%">{{ _("Rate") }}</th>
				<th class="num" style="width: 14%">{{ _("Discount") }}</th>
				<th class="num" style="width: 14%">{{ _("Amount") }}</th>
			</tr>
		</thead>
		<tbody>
			{% for item in doc.items %}
			<tr>
				<td class="center">{{ loop.index }}</td>
				<td>{{ item.item_code }}</td>
				<td>
					<div>{{ item.item_name }}</div>
					{% if item.description %}
					<div class="item-desc">{{ item.description }}</div>
					{% endif %}
				</td>
				<td class="center">{{ item.get_formatted("qty", doc) }}</td>
				<td class="center">{{ item.uom or "" }}</td>
				<td class="num">{{ doc.currency }} {{ frappe.utils.fmt_money(item.rate) }}</td>
				<td class="num">{{ doc.currency }} {{ frappe.utils.fmt_money(frappe.utils.flt(item.qty) * frappe.utils.flt(item.discount_amount)) }}</td>
				<td class="num">{{ doc.currency }} {{ frappe.utils.fmt_money(item.amount) }}</td>
			</tr>
			{% endfor %}
		</tbody>
		<tfoot>
			<tr>
				<td colspan="3">{{ _("Total Quantity") }}</td>
				<td class="center">{{ doc.get_formatted("total_qty", doc) }}</td>
				<td></td>
				<td></td>
				<td class="num">{{ doc.currency }} {{ frappe.utils.fmt_money(ns.item_discount_total) }}</td>
				<td class="num">{{ doc.currency }} {{ frappe.utils.fmt_money(doc.total) }}</td>
			</tr>
		</tfoot>
	</table>

	<div class="clearfix" style="margin-top: 14px">
		<table class="totals-table">
			<tr>
				<td>{{ _("Subtotal") }}</td>
				<td class="t-value">{{ doc.currency }} {{ frappe.utils.fmt_money(doc.total) }}</td>
			</tr>
			{% if doc.discount_amount %}
			<tr>
				<td>{{ _("Discount") }}</td>
				<td class="t-value">{{ doc.currency }} {{ frappe.utils.fmt_money(doc.discount_amount) }}</td>
			</tr>
			{% endif %}
			<tr class="grand">
				<td>{{ _("Grand Total") }}</td>
				<td class="t-value">{{ doc.currency }} {{ frappe.utils.fmt_money(doc.grand_total) }}</td>
			</tr>
		</table>

		<div class="words-bank">
			<div class="words-box">
				<div class="section-label">{{ _("Amount in Words") }}</div>
				<div>{{ doc.in_words }}</div>
			</div>
			{% if bank_account %}
			<div class="bank-details">
				<div class="section-label">{{ _("Bank Details") }}</div>
				<table class="bank-table">
					{% if bank_account.account_name %}
					<tr><td class="b-label">{{ _("Account Name") }}</td><td>{{ bank_account.account_name }}</td></tr>
					{% endif %}
					{% if bank_name %}
					<tr><td class="b-label">{{ _("Bank") }}</td><td>{{ bank_name }}</td></tr>
					{% endif %}
					{% if bank_account.bank_account_no %}
					<tr><td class="b-label">{{ _("Account No.") }}</td><td>{{ bank_account.bank_account_no }}</td></tr>
					{% endif %}
					{% if bank_account.iban %}
					<tr><td class="b-label">{{ _("IBAN") }}</td><td>{{ bank_account.iban }}</td></tr>
					{% endif %}
					{% if bank_swift %}
					<tr><td class="b-label">{{ _("SWIFT") }}</td><td>{{ bank_swift }}</td></tr>
					{% endif %}
				</table>
			</div>
			{% endif %}
		</div>
	</div>

	{% if doc.terms %}
	<div class="terms">
		<div class="section-label">{{ _("Terms & Conditions") }}</div>
		<div>{{ doc.terms }}</div>
	</div>
	{% endif %}

	<div class="signature">
		<div class="line">{{ _("Received by") }} &mdash; {{ _("name, signature & date") }}</div>
	</div>
</div>

<div {% if print_settings.repeat_header_footer %} id="footer-html" class="visible-pdf" {% endif %}>
	<div class="ls-order">
		<div class="print-footer" style="border-top: 1px solid #000; padding-top: 4px; margin-top: 10px;">
			<span>{{ doc.company }}{% if company_website %} &middot; {{ company_website }}{% endif %}</span>
			{% if print_settings.repeat_header_footer %}
			<span>{{ _("Page {0} of {1}").format('<span class="page"></span>', '<span class="topage"></span>') }}</span>
			{% endif %}
		</div>
	</div>
</div>
